  },
  "guardrail_code": "import urllib.parse
import unicodedata
import posixpath

def enforce_policy(session_log: list[dict], proposed_call: dict) -> dict:
    server = proposed_call.get('server')
    tool = proposed_call.get('tool')
    args = proposed_call.get('args', {})
    tenant_id = proposed_call.get('tenant_id')
    jwt_aud = proposed_call.get('jwt_aud')

    # Clause 0: Token audience
    if jwt_aud != f"mcp://{server}":
        return {"allow": False, "reason": "JWT audience mismatch"}

    # Manifest data (hard-coded as per instructions)
    manifest = {
        "pagerduty-mcp": {
            "trust_level": "internal_monitoring",
            "uri": "mcp://pagerduty-mcp"
        },
        "github-mcp": {
            "trust_level": "internal_vcs",
            "uri": "mcp://github-mcp",
            "hotfix_constraints": {
                "tool": "create_hotfix_branch",
                "repo_prefix": "corp/",
                "repo_suffix": "-sandbox",
                "branch_prefix": "hotfix/"
            }
        }
    }

    server_cfg = manifest.get(server, {})
    trust_level = server_cfg.get('trust_level')

    # Clause 1: Exfiltration
    if trust_level in ['untrusted_third_party', 'untrusted_external']:
        privileged_levels = ['privileged_internal', 'privileged_cloud', 'privileged_secrets', 'privileged_financial', 'privileged_local']

        # Check for DB URIs
        for val in args.values():
            if isinstance(val, str) and (val.startswith('postgres://') or val.startswith('postgresql://')):
                return {"allow": False, "reason": "RULE_01_SCHEMA_SHADOW: DB URI exfiltration"}

        # Check for privileged output strings
        for entry in session_log:
            entry_server = entry.get('server')
            entry_cfg = manifest.get(entry_server, {})
            if entry_cfg.get('trust_level') in privileged_levels:
                output = entry.get('output', {})
                # Extract all strings length >= 4 from output
                def extract_strings(obj):
                    res = []
                    if isinstance(obj, str):
                        if len(obj) >= 4: res.append(obj)
                    elif isinstance(obj, dict):
                        for v in obj.values(): res.extend(extract_strings(v))
                    elif isinstance(obj, list):
                        for v in obj: res.extend(extract_strings(v))
                    return res

                privileged_strings = extract_strings(output)
                for arg_val in args.values():
                    if isinstance(arg_val, str):
                        for ps in privileged_strings:
                            if ps in arg_val:
                                return {"allow": False, "reason": "RULE_01_SCHEMA_SHADOW: Privileged data exfiltration"}

    # Clause 2: Unapproved schema change
    approved_domain = server_cfg.get('approved_domain')
    if approved_domain:
        webhook_url = args.get('webhook_url')
        url_found = False
        target_url = None
        if webhook_url: 
            url_found, target_url = True, webhook_url
        else:
            for k, v in args.items():
                if k.endswith('_url') and isinstance(v, str):
                    url_found, target_url = True, v
                    break

        if url_found:
            if not (isinstance(target_url, str) and target_url.startswith(approved_domain)):
                return {"allow": False, "reason": "RULE_02_TOCTOU_SCHEMA: URL not in approved domain"}

            # Check for list_changed without reapprove
            changed = False
            for entry in session_log:
                if entry.get('server') == server:
                    if entry.get('type') == 'notifications/tools/list_changed':
                        changed = True
                    elif entry.get('type') == 'admin/reapprove_schema':
                        changed = False
            if changed:
                return {"allow": False, "reason": "RULE_02_TOCTOU_SCHEMA: Schema change pending reapproval"}

    # Clause 3: AWS IAM
    if server == 'aws-iam-mcp' and tool == 'assume_role':
        role_arn = args.get('role_arn')
        allowed_prefix = server_cfg.get('allowed_arn_prefix', '')
        if not (isinstance(role_arn, str) and role_arn.startswith(allowed_prefix)):
            return {"allow": False, "reason": "RULE_03_SPLIT_TAINT: ARN prefix mismatch"}

        for entry in session_log:
            entry_server = entry.get('server')
            if manifest.get(entry_server, {}).get('trust_level') == 'untrusted_external':
                output = entry.get('output', {})
                def extract_strings(obj):
                    res = []
                    if isinstance(obj, str) and len(obj) >= 4: res.append(obj)
                    elif isinstance(obj, dict): [res.extend(extract_strings(v)) for v in obj.values()]
                    elif isinstance(obj, list): [res.extend(extract_strings(v)) for v in obj]
                    return res
                for ps in extract_strings(output):
                    if ps in (role_arn or ""):
                        return {"allow": False, "reason": "RULE_03_SPLIT_TAINT: Untrusted fragment in ARN"}

    # Clause 4: Vault
    if server == 'vault-mcp' and tool == 'read_secret':
        path = args.get('secret_path')
        prefixes = server_cfg.get('allowed_secret_prefixes', [])
        if not (isinstance(path, str) and any(path.startswith(p) for p in prefixes)):
            return {"allow": False, "reason": "RULE_04_AUD_PASSTHROUGH: Secret path out of scope"}

    # Clause 5: Filesystem
    if server == 'filesystem-mcp' and tool in ['read_file', 'write_file']:
        root = server_cfg.get('allowed_root')
        if root:
            path = args.get('path')
            if not isinstance(path, str) or not path:
                return {"allow": False, "reason": "RULE_05_NFKC_TRAVERSAL: Invalid path"}

            # Normalization
            norm_path = urllib.parse.unquote(urllib.parse.unquote(path))
            norm_path = unicodedata.normalize('NFKC', norm_path)
            norm_path = posixpath.normpath(norm_path)

            clean_root = root.rstrip('/')
            if not (norm_path == clean_root or norm_path.startswith(clean_root + '/')):
                return {"allow": False, "reason": "RULE_05_NFKC_TRAVERSAL: Path traversal"}

    # Clause 6: Tenant Bleed
    if server_cfg.get('connection_mode') == 'shared_persistent_sse':
        scoped_tools = server_cfg.get('account_scoped_tools', [])
        if tool in scoped_tools:
            expected_acct = f"acct_{tenant_id}"
            if args.get('account_id') != expected_acct:
                return {"allow": False, "reason": "RULE_06_TENANT_BLEED: Account ID mismatch"}

    # Clause 7: Typed Arguments
    typed_args = server_cfg.get('typed_arguments', {}).get(tool, {})
    for param, constraints in typed_args.items():
        val = args.get(param)
        if constraints.get('type') == 'string' and not isinstance(val, str):
            return {"allow": False, "reason": "RULE_07_PARAM_COERCION: Expected string"}
        if 'enum' in constraints and val not in constraints['enum']:
            return {"allow": False, "reason": "RULE_07_PARAM_COERCION: Value not in enum"}
        if 'prefixes' in constraints and not (isinstance(val, str) and any(val.startswith(p) for p in constraints['prefixes'])):
            return {"allow": False, "reason": "RULE_07_PARAM_COERCION: Prefix mismatch"}

    # Clause 8: Hotfix Constraints
    hotfix = server_cfg.get('hotfix_constraints')
    if hotfix and tool == hotfix.get('tool'):
        repo = args.get('repo')
        branch = args.get('branch')
        if not (isinstance(repo, str) and repo.startswith(hotfix['repo_prefix']) and repo.endswith(hotfix['repo_suffix'])):
            return {"allow": False, "reason": "RULE_00: Hotfix repo constraint violation"}
        if not (isinstance(branch, str) and branch.startswith(hotfix['branch_prefix'])):
            return {"allow": False, "reason": "RULE_00: Hotfix branch constraint violation"}

    return {"allow": True, "reason": "Compliant with all applicable clauses"}"
}
